fn fib(n: Int) -> Int {
    let a = 1
    let b = 1
    if n == 1 || n == 2 {
        return 1
    }
    let mut i = 3
    let mut c = 0
    while i <= n {
        c = a + b
        a = b
        b = c
        i += 1
    }
    c
}

